#!/usr/bin/env bash
set -euo pipefail
ARM="${CEILING1_STAGE2_ARM:?}"; C="${CEILING1_STAGE2_CONTAINER:?}"; UUID="${CEILING1_STAGE2_GPU_UUID:?}"; WT="${CEILING1_AUTOPILOT_REPO:?}"; ROOT="${CEILING1_ANALYSIS_ROOT:?}"; CFGSHA="${CEILING1_STAGE2_CONFIG_SHA:?}"; SID="${CEILING1_STAGE1_STATE_ID:?}"
MODEL="$ROOT/stage2-base/$ARM"; SEAL="${CEILING1_STAGE1_SEAL:-$ROOT/STAGE1_COMPLETE_${ARM}.json}"; REV="$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["base_revision"])' "$MODEL/merge-receipt.json")"; HARNESS="${CEILING1_STAGE2_HARNESS_PROFILE:-legacy}"; CARRIER_ROOT="${CEILING1_HARNESS201_CARRIER_ROOT:-}"; if [[ "$HARNESS" == "2.0.1" || "$HARNESS" == "201.1" ]]; then [[ -n "$CARRIER_ROOT" && -s "$CARRIER_ROOT/finalize-receipt.json" ]] || { echo "NO-GO Harness201 carrier seed missing" >&2; exit 20; }; MEM="$CARRIER_ROOT/memory.md"; SK="$CARRIER_ROOT/skill.md"; AG="$CARRIER_ROOT/agent.md"; carrierargs=(--carrier-seed-receipt "$CARRIER_ROOT/finalize-receipt.json"); else MEM="$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["text_memory"]["path"])' "$SEAL")"; SK="$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["skill_bundle"]["path"])' "$SEAL")"; AG="$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["agent_system"]["path"])' "$SEAL")"; carrierargs=(); fi; OUT="$ROOT/stage2-preflight/$ARM"
docker run -d --name "$C" --restart no --gpus "device=$UUID" --network none --user 1001:1001 -e CUDA_VISIBLE_DEVICES="$UUID" -e TRANSFORMERS_OFFLINE=1 -e HF_HUB_OFFLINE=1 -e PYTHONPATH="$WT:$WT/vendor/openevo-webshop/src:/workspace/control/openevo-core/src" -v "$WT:$WT:ro" -v /workspace/control/openevo-core:/workspace/control/openevo-core:ro -v "$ROOT:$ROOT" --entrypoint /usr/local/bin/python3 experiment-host/openevo-scientific:h144-runtime-v1 "$WT/scripts/openevo_webshop/verify_ceiling1_stage2_initial_state.py" --model "$MODEL" --revision "$REV" --memory "$MEM" --skill "$SK" --agent-system "$AG" --gpu-uuid "$UUID" --output "$OUT/runtime-preflight.json" --stage1-state-id "$SID" --stage2-config-sha256 "$CFGSHA" --harness-profile "$HARNESS" "${carrierargs[@]}" >/dev/null
